DZI.unknown = [
  {"author": "Иван Вазов", "title": "Отечество любезно, как хубаво си ти!", "excerpt": "Ти рай си, да; но кой те прилично оценява?\nНе те познават даже децата ти сами\nи твойто име свято не рядко ги срами!\nКакъв ли свят прекрасен в теб йоще скрит остава?\nКакви ли тайни дремят, богатства, красоти\nпо твоите долини, поля и висоти?\nТи рай си, да; но кой те прилично оценява?\n\nАх, ний живейме в тебе, кат същи чужденци,\nи твоят дивен вид ни не стряска, не привлича.\nРогачът в планините по-много те обича,\nпо-харно те познават крилатите певци,\nно ний не видим нищо, нам нищо не ни тряба,\nдоволно е, че даваш покривката и хляба,\nи ние в тебе, майко, ще умрем чужденци!", "q": "Коя тема е интерпретирана в откъса от стихотворението „Отечество любезно, как хубаво си ти!“ на Иван Вазов?", "o": ["Родното и чуждото", "Трудът и творчеството", "Изборът и раздвоението", "Вярата и надеждата"], "e": "Откъсът противопоставя красотата на родината („Ти рай си“) на отчуждението на нейните деца, които живеят в нея „кат същи чужденци“ – тема за родното и чуждото."},
  {"author": "Димчо Дебелянов", "title": "Помниш ли, помниш ли тихия двор…", "excerpt": "Помниш ли, помниш ли тихия двор,\nтихия дом в белоцветните вишни? —\nАх, не проблясвайте в моя затвор,\nжалби далечни и спомени лишни —\nаз съм заключеник в мрачен затвор,\nжалби далечни и спомени лишни,\nмоята стража е моят позор,\nмоята казън са дните предишни!\n\nПомниш ли, помниш ли в тихия двор\nшъпот и смях в белоцветните вишни? —\nАх, не пробуждайте светлия хор,\nхорът на ангели в дните предишни —\nаз съм заключеник в мрачен затвор,\nжалби далечни и спомени лишни,\nсън е бил, сън е бил тихия двор,\nсън са били белоцветните вишни!", "q": "Коя тема е интерпретирана в стихотворението „Помниш ли, помниш ли тихия двор…“ на Димчо Дебелянов?", "o": ["Миналото и паметта", "Природата", "Обществото и властта", "Трудът и творчеството"], "e": "Лирическият говорител е „заключеник“ на спомена – „дните предишни“, тихият двор и белоцветните вишни са изгубеното минало, което паметта връща като болка."},
  {"author": "Христо Смирненски", "title": "Зимни вечери", "excerpt": "Вървя край смълчаните хижи\nв море непрогледна мъгла\nи вечната бедност и грижа\nме гледат през мътни стъкла.\n\nВ стъклата с десница незрима,\nпод ледния дъх на нощта,\nчертала е бялата зима\nнеземни сребристи цветя.\n\nНо ето къщурка позната;\nв прозореца детска глава;\nи грубо гърмят в тишината\nпияни хрипливи слова.\n\nЗавърнал се вкъщи — безхлебен,\nпиян пак, — бащата ругай:\nи своя живот непотребен,\nи своята мъка без край.\n\nЗавесата мръсна, продрана\nи едър мъглив силует,\nразмахва ръцете в закана,\nот помисли странни обзет.\n\nДецата пищят и се молят,\nа вънка, привела глава,\nсред своята скръб и неволя\nжена проридава едва.", "q": "Коя тема е интерпретирана в откъса от стихотворението „Зимни вечери“ на Христо Смирненски?", "o": ["Обществото и властта", "Любовта", "Миналото и паметта", "Изборът и раздвоението"], "e": "Откъсът рисува „вечната бедност и грижа“ на града – безхлебния и пиян баща, плачещите деца и жената – социалната неправда, т.е. тема за обществото."},
  {"author": "Димчо Дебелянов", "title": "Сиротна песен", "excerpt": "Ако загина на война,\nжал никого не ще попари —\nизгубих майка, а жена\nне найдох, нямам и другари.\n\nАла сърце ми не скърби —\nприневолен живя сирака\nи за утеха, може би,\nсмъртта в победа ще дочака.\n\nПознавам своя път нерад,\nбогатствата ми са у мене,\nче аз съм с горести богат\nи с радости несподелени.\n\nЩе си отида от света —\nтъй както съм дошъл бездомен,\nспокоен като песента,\nнавяваща ненужен спомен.", "q": "Коя тема е интерпретирана в стихотворението „Сиротна песен“ на Димчо Дебелянов?", "o": ["Животът и смъртта", "Природата", "Трудът и творчеството", "Родното и чуждото"], "e": "Лирическият говорител размисля за възможната си гибел на война и равносметката на самотния си живот („Ще си отида от света – / тъй както съм дошъл бездомен“) – тема за живота и смъртта."},
  {"author": "Димчо Дебелянов", "title": "Гора", "excerpt": "Накрай полето, дето плавно излъчва слънцето стрели\nи в марни валози потокът с вълни приспивни ръмоли,\nмеда на отдиха стаила дълбоко в девствени недра,\nвиши колони непреклонни успокоената Гора.\n\nТам дремят приказки старинни, там тае звънка тишина\nи в безответните й скути, като вълна подир вълна,\nзаглъхват хоровете страстни на многогласното поле\nи подслон верен в час вечерен намират морните криле.\n\nИ знае пътникът отруден, че в презнощ тръпните листа\nс участен ромон ще му спомнят на миналото повестта,", "q": "Коя тема е интерпретирана в откъса от стихотворението „Гора“ на Димчо Дебелянов?", "o": ["Природата", "Обществото и властта", "Трудът и творчеството", "Изборът и раздвоението"], "e": "Гората е изобразена като тихо, успокояващо убежище („подслон верен в час вечерен“) за морните криле и за отрудения пътник – тема за природата."},
  {"author": "Христо Смирненски", "title": "Да бъде ден!", "excerpt": "Нощта е черна и зловеща,\nнощта е ледна като смърт.\nВ разкъсаната земна гръд\nструи се бавно кръв гореща.\nВ димящите развалини\nбезокий демон на войната\nразвял е хищно знамената\nи меч въз меч безспир звъни.\nСред мрака непрогледно гъст\nстърчи злокобен силует\nна някакъв грамаден кръст,\nи хилядни тълпи отвред\nвървят, подгонени натам\nот яростта на златний бог.\nИ мрака става по-дълбок,\nтълпите нижат се едвам.\nЗа въздух жадни са гърдите,\nочите молят светлина,\nедин копнеж, мечта една\nгори и се топи в душите\nи през сълзи и кървав гнет,\nпрез ужаса на мрак студен\nразбунен вик гърми навред:\n«Да бъде ден! Да бъде ден!».", "q": "Коя тема е интерпретирана в стихотворението „Да бъде ден!“ на Христо Смирненски?", "o": ["Вярата и надеждата", "Любовта", "Природата", "Трудът и творчеството"], "e": "Сред мрака и ужаса на войната в душите гори „един копнеж, мечта една“, която прераства в разбунения вик „Да бъде ден!“ – надеждата за светлина и избавление."},
  {"author": "Никола Вапцаров", "title": "Завод", "excerpt": "Завод. Над него облаци от дим.\nНародът прост,\nживотът — тежък, скучен. —\nЖивот без маска и без грим —\nозъбено, свирепо куче.\n\nИ трябва да се бориш неуморно,\nи трябва да си страшно упорит,\nза да изтръгнеш от зъбите\nна туй настръхнало,\nвбесено псе\nпарченце хлеб.\n\nВъв залите плющят каиши,\nтрансмисии скриптят\nот всеки кът.\nИ става толкоз душно,\nче да дишаш\nне би могъл спокойно,\nс пълна гръд.\n(…)\nЕдна ръка изхвърли на боклука\nидилиите с синьото небе.\nЗащото миг на некаква заблуда,\nзащото миг с размекнато сърце,\nби значело напразно да загубиш\nработните си\nжилави\nръце.", "q": "Коя тема е интерпретирана в откъса от стихотворението „Завод“ на Никола Вапцаров?", "o": ["Трудът и творчеството", "Любовта", "Миналото и паметта", "Родното и чуждото"], "e": "Откъсът представя тежкия заводски труд – шума на машините, задуха и борбата за „парченце хлеб“ с „работните си / жилави / ръце“ – тема за труда."},
  {"author": "Димчо Дебелянов", "title": "Черна песен", "excerpt": "Аз умирам и светло се раждам —\nразнолика, нестройна душа,\nпрез деня неуморно изграждам,\nпрез нощта без пощада руша.\n\nПризова ли дни светло-смирени,\nгръмват бури над тъмно море,\nа подиря ли буря — край мене\nвсеки вопъл и ропот замре.\n\nЗа зора огнеструйна копнея,\nа слепи ме с очите си тя,\nв пролетта като в есен аз крея,\nв есента като в пролет цъфтя.\n\nНа безстрастното време в неспира\nгасне мълком живот неживян,\nи плачът ми за пристан умира\nниз велика пустиня развян.", "q": "Коя тема е интерпретирана в стихотворението „Черна песен“ на Димчо Дебелянов?", "o": ["Изборът и раздвоението", "Родното и чуждото", "Обществото и властта", "Любовта"], "e": "„Разнолика, нестройна душа“, която денем изгражда, а нощем руши, и антитезите (пролет – есен, буря – покой) изразяват раздвоението на лирическия говорител."}
];

